import contextlib,datetime,re,sqlite3
from zoneinfo import ZoneInfo,ZoneInfoNotFoundError
UTC=datetime.timezone.utc
def day_slot(day,zone,clock):
    if not isinstance(day,str) or re.fullmatch(r'\d{4}-\d{2}-\d{2}',day) is None:raise ValueError('ISO business date required')
    if not isinstance(clock,str) or re.fullmatch(r'\d{2}:\d{2}',clock) is None:raise ValueError('HH:MM required')
    date=datetime.date.fromisoformat(day);hour,minute=map(int,clock.split(':'))
    naive=datetime.datetime.combine(date,datetime.time(hour,minute))
    try:timezone=ZoneInfo(zone)
    except (ZoneInfoNotFoundError,TypeError) as error:raise ValueError('known IANA zone required') from error
    candidates=set()
    for fold in (0,1):
        instant=naive.replace(tzinfo=timezone,fold=fold).astimezone(UTC)
        if instant.astimezone(timezone).replace(tzinfo=None)==naive:candidates.add(instant)
    if not candidates:return {'kind':'gap','utc':None}
    return {'kind':'fold' if len(candidates)==2 else 'unique','utc':min(candidates).isoformat()}
def claim(db_path,job,day,zone,clock,approved_dates,now_utc):
    if not isinstance(job,str) or not job or day not in approved_dates:raise ValueError('approved business day and job required')
    slot=day_slot(day,zone,clock)
    now=datetime.datetime.fromisoformat(now_utc)
    if now.tzinfo is None or now.utcoffset()!=datetime.timedelta(0):raise ValueError('explicit UTC callback time required')
    with contextlib.closing(sqlite3.connect(db_path,timeout=3)) as db:
        with db:
            db.execute('CREATE TABLE IF NOT EXISTS calendar_runs(job TEXT,business_date TEXT,zone TEXT,clock TEXT,slot_utc TEXT,PRIMARY KEY(job,business_date))')
            db.execute('BEGIN IMMEDIATE')
            old=db.execute('SELECT zone,clock,slot_utc FROM calendar_runs WHERE job=? AND business_date=?',(job,day)).fetchone()
            if old:
                if old!=(zone,clock,slot['utc']):raise ValueError('existing business day rebound to a new schedule')
                return {'state':'already_claimed',**slot}
            if slot['kind']=='gap':return {'state':'manual_gap',**slot}
            if now<datetime.datetime.fromisoformat(slot['utc']):return {'state':'not_due',**slot}
            db.execute('INSERT INTO calendar_runs VALUES(?,?,?,?,?)',(job,day,zone,clock,slot['utc']))
            return {'state':'claimed',**slot}
